changeSet.sql:
ALTER TABLE IF EXISTS reglements_fournisseur DROP CONSTRAINT IF EXISTS reglements_fournisseur_mode_paiement_check;
ALTER TABLE IF EXISTS reglements_fournisseur ADD CONSTRAINT reglements_fournisseur_mode_paiement_check CHECK (mode_paiement IN ( 'ESPECES', 'CARTE_BANCAIRE', 'CHEQUE', 'VIREMENT', 'CREDIT', 'TRAITE', 'EFFET', 'LCN', 'AVIS_DEBIT' ));
ALTER TABLE IF EXISTS paiements DROP CONSTRAINT IF EXISTS paiements_mode_paiement_check;
ALTER TABLE IF EXISTS paiements ADD CONSTRAINT paiements_mode_paiement_check CHECK (mode_paiement IN ( 'ESPECES', 'CARTE_BANCAIRE', 'CHEQUE', 'VIREMENT', 'CREDIT', 'TRAITE', 'EFFET', 'LCN', 'AVIS_DEBIT' ));
